export const MESSAGES = Object.freeze({ da:Object.freeze(DA), de:Object.freeze(DE), en:Object.freeze(EN) });
const EXTENDED_MESSAGES = { da:{}, de:{}, en:{} };

export function registerI18nMessages(messages = {}) {
  for (const language of LANGUAGE_CODES) {
    const additions = messages?.[language];
    if (!additions || typeof additions !== 'object' || Array.isArray(additions)) continue;
    Object.assign(EXTENDED_MESSAGES[language], additions);
  }
}

export function hasTranslation(key, language = getLanguage()) {
  const code = normaliseLanguage(language);
  return Object.hasOwn(EXTENDED_MESSAGES[code], key) || Object.hasOwn(MESSAGES[code], key) ||
    Object.hasOwn(EXTENDED_MESSAGES.da, key) || Object.hasOwn(MESSAGES.da, key);
}

function storedLanguage() {
  try { return globalThis.localStorage?.getItem(STORAGE_KEY); } catch { return null; }
}

export function normaliseLanguage(value) {
  const code = String(value || '').trim().toLowerCase().split('-')[0];
  return LANGUAGE_CODES.has(code) ? code : 'da';
}

export function getLanguage() {
  return normaliseLanguage(storedLanguage());
}

export function getLocale(language = getLanguage()) {
  return SUPPORTED_LANGUAGES.find(item => item.code === normaliseLanguage(language))?.locale || 'da-DK';
}

export function setLanguage(language) {
  const code = normaliseLanguage(language);
  try { globalThis.localStorage?.setItem(STORAGE_KEY, code); } catch {}
  return code;
}

export function t(key, params = {}, language = getLanguage()) {
  const code = normaliseLanguage(language);
  const template = EXTENDED_MESSAGES[code]?.[key] ?? MESSAGES[code]?.[key] ?? EXTENDED_MESSAGES.da[key] ?? MESSAGES.da[key] ?? key;
  return String(template).replace(/\{([A-Za-z0-9_]+)\}/g, (match, name) => Object.hasOwn(params, name) ? String(params[name]) : match);
}

export function formatNumber(value, options = {}, language = getLanguage()) {
  const number = Number(value);
  return Number.isFinite(number) ? new Intl.NumberFormat(getLocale(language), options).format(number) : t('common.missing', {}, language);
}

export function formatDateTime(value, options = { dateStyle:'medium', timeStyle:'short' }, language = getLanguage()) {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isFinite(date.getTime()) ? new Intl.DateTimeFormat(getLocale(language), options).format(date) : t('common.missing', {}, language);
}

function translateAttribute(root, selector, attribute, dataAttribute) {
  root.querySelectorAll?.(selector).forEach(element => element.setAttribute(attribute, t(element.dataset[dataAttribute])));
}

export function applyDocumentTranslations(root = globalThis.document) {
  if (!root) return;
  const language = getLanguage();
  const documentElement = root.documentElement || root.ownerDocument?.documentElement;
  if (documentElement) documentElement.lang = language;
  root.querySelectorAll?.('[data-i18n]').forEach(element => { element.textContent = t(element.dataset.i18n); });
  root.querySelectorAll?.('[data-i18n-html]').forEach(element => {
    if (hasTranslation(element.dataset.i18nHtml, language)) element.innerHTML = t(element.dataset.i18nHtml, {}, language);
  });
  translateAttribute(root, '[data-i18n-aria-label]', 'aria-label', 'i18nAriaLabel');
  translateAttribute(root, '[data-i18n-title]', 'title', 'i18nTitle');
  translateAttribute(root, '[data-i18n-placeholder]', 'placeholder', 'i18nPlaceholder');
  translateAttribute(root, '[data-i18n-content]', 'content', 'i18nContent');
  translateAttribute(root, '[data-i18n-alt]', 'alt', 'i18nAlt');
  const title = root.querySelector?.('title');
  if (title) title.textContent = t(title.dataset.i18n || 'meta.title');
  const description = root.querySelector?.('meta[name="description"]');
  if (description && !description.dataset.i18nContent) description.setAttribute('content', t('meta.description'));
  root.querySelectorAll?.('[data-language]').forEach(button => {
    const active = normaliseLanguage(button.dataset.language) === language;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
}

export function installLanguageSwitcher(root = globalThis.document) {
  if (!root) return;
  root.querySelectorAll?.('[data-language]').forEach(button => button.addEventListener('click', () => {
    const next = setLanguage(button.dataset.language);
    if (next === getLanguage()) globalThis.location?.reload?.();
  }));
}

export function initialiseI18n(root = globalThis.document) {
  applyDocumentTranslations(root);
  installLanguageSwitcher(root);
  return getLanguage();
}

export const I18N_STORAGE_KEY = STORAGE_KEY;
